import{_ as o,l,o as t,c as s,v as e,p as n,x as i,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"路径导数与似然比","description":"","frontmatter":{"title":"路径导数与似然比","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pathwise-likelihood-ratio.md","filePath":"quant/pathwise-likelihood-ratio.md","lastUpdated":1789023840000}'),E={name:"quant/pathwise-likelihood-ratio.md"};function m(B,a,c,A,_,u){const r=l("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="路径导数与似然比" tabindex="-1">路径导数与似然比 <a class="header-anchor" href="#路径导数与似然比" aria-label="Permalink to &quot;路径导数与似然比&quot;">​</a></h1><div class="epigraph"><p>路径导数对平滑支付方差小；似然比把导数转到密度上，能穿过间断，但方差随时间变长。</p><footer>—— Broadie and Glasserman, Estimating Security Price Derivatives Using Simulation, Management Science, 1996</footer></div><p><a href="/quant/aad-adjoint">上一课</a>把计算图倒过来，默认对象仍是路径wise 的 \\(\\partial\\mathrm{payoff}/\\partial\\theta\\)。本课的缺口是蒙特卡洛希腊值的<strong>两条经典估计</strong>：路径导数（pathwise）与似然比（likelihood ratio / score）。后课 Vega 桶用这些估计去填曲面风险；这里先写何时哪一条不炸方差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限差分模拟：每 bump 一次要重新抽路径，噪声大，偏差与步长纠缠。路径导数在同一路径上对支付函数求导：若支付对 \\(S\\) Lipschitz、几乎处处可微，期望与导数可换序，得到无偏估计。数字与障碍的支付不连续，换序失败，路径导数在触发路径上是 0 或未定义，估计<strong>偏低</strong>。似然比不碰支付，而对转移密度取对数导（score），间断支付也能用，代价是 score 的方差随模拟步数恶化。</p><p>问题不是选一个「更好的希腊值」，而是按支付光滑度与参数类型（水平参数 vs 波动参数）搭配，或做混合。</p><h3 id="换序条件不是一句「几乎处处」" tabindex="-1">换序条件不是一句「几乎处处」 <a class="header-anchor" href="#换序条件不是一句「几乎处处」" aria-label="Permalink to &quot;换序条件不是一句「几乎处处」&quot;">​</a></h3><p>路径导数要求 \\(\\mathbb{E}[\\partial_\\theta f(S(\\theta))]\\) 存在且等于 \\(\\partial_\\theta\\mathbb{E}[f]\\)。示性函数 \\(\\mathbf{1}_{S_T\\gt K}\\) 对 \\(S_T\\) 的导数是 Dirac，模拟里看不见，估计变成 0。把数字平滑成窄价差，路径导数回来，但估的是价差不是数字——与 <a href="/quant/digital-options">数字</a> 的复制一致，这是特征不是 bug。</p><p><span class="marginnote">波动率进入扩散系数时，路径导数要对 SDE 的变分过程（tangent process）积分，不能只对终点解析式里的 \\(\\sigma\\) 写偏导。GBM 闭式还能手写；局部波动与 Heston 必须联立变分方程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路径导数：对每条路径求 \\(\\partial\\mathrm{payoff}/\\partial\\theta\\)，平均。GBM 香草 Delta/Vega 有显式。似然比：\\(\\widehat{\\partial_\\theta V}=\\mathrm{payoff}\\times\\partial_\\theta\\log p\\)，其中 \\(p\\) 是路径密度。重要性采样与似然比同源，可共用 score。混合：对平滑部分路径导数，对间断用似然比或 Malliavin 权。AAD 用来算路径导数的变分，不自动解决间断。</p><p>实践：障碍用布朗桥触碰概率做平滑；数字用价差；美式用回归后的连续近似价值再路径求导。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>路径导数利用的是<strong>同一随机源</strong>下支付对参数的 Lipschitz 依赖；似然比利用的是测度对参数的绝对连续。前者方差通常更小，因为支付与导数同路径强相关；后者把所有随机性推到密度上，支付越大 score 噪声越大。时间步一多，score 是很多高斯增量导数之和，方差近似线性涨。这就是为什么长期限 XVA 不用裸似然比去估全部曲线节点。</p>',14)),(t(),n(d,null,{default:i(()=>[p(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Smooth%5B%22%E5%B9%B3%E6%BB%91%E6%94%AF%E4%BB%98%22%5D%20--%3E%20PW%5B%22%E8%B7%AF%E5%BE%84%E5%AF%BC%E6%95%B0%20%E6%96%B9%E5%B7%AE%E5%B0%8F%22%5D%0A%20%20Jump%5B%22%E6%95%B0%E5%AD%97%20%E9%9A%9C%E7%A2%8D%22%5D%20--%3E%20LR%5B%22%E4%BC%BC%E7%84%B6%E6%AF%94%20%E7%A9%BF%E8%BF%87%E9%97%B4%E6%96%AD%22%5D%0A%20%20Jump%20--%3E%20Sm%5B%22%E5%B9%B3%E6%BB%91%E6%88%90%E4%BB%B7%E5%B7%AE%E5%86%8D%E8%B7%AF%E5%BE%84%E5%AF%BC%22%5D%0A%20%20LR%20--%3E%20Var%5B%22%E6%96%B9%E5%B7%AE%E9%9A%8F%E6%AD%A5%E6%95%B0%E5%8F%98%E5%B7%AE%22%5D%0A%20%20PW%20--%3E%20AAD%5B%22AAD%20%E5%8A%A0%E9%80%9F%E5%8F%98%E5%88%86%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>似然比对离散观察障碍仍要求密度对参数可微；对「是否触碰」这种硬判据，要把触碰写进密度（桥）而不是写进支付。Malliavin 权是似然比的连续时间版，实现成本高，本课不展开。不要对已经用对照变量减过方差的同一批路径再盲目套似然比而不重新设计权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>路径导数适合平滑支付，间断时系统性偏；似然比能穿过间断，方差较差。</li><li>数字用价差平滑后走路径导数，与复制一致。</li><li>AAD 加速路径导数，不替代换序条件。</li><li>出处：Broadie and Glasserman, <em>Management Science</em>, 1996。</li></ul>',4))])}const g=o(E,[["render",m]]);export{D as __pageData,g as default};
